// Generated by tabmill (templates/extension/_shared) — do not edit (ADR-0008).
// Renders extension + Chrome Web Store images with Playwright's Chromium (builder container).
//   node scripts/assets.mjs icons   assets/icon.svg → public/icon/{16,32,48,128}.png
//   node scripts/assets.mjs store   .output/chrome-mv3 → .output/store/{icon-128,promo-440x280,
//                                    screenshot-N}.png (needs a build)
// Sizes: developer.chrome.com/docs/webstore/images (verified 2026-10-03).
import { chromium } from "@playwright/test";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const svg = readFileSync(path.join(root, "assets/icon.svg"), "utf8");
const svgUri = `data:image/svg+xml;base64,${Buffer.from(svg).toString("base64")}`;
const cfg = JSON.parse(readFileSync(path.join(root, "scripts/store.json"), "utf8"));
const mode = process.argv[2];
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

const STAGE_CSS = `html,body{margin:0}body{font-family:ui-sans-serif,system-ui,sans-serif;color:#0f172a}`;

async function shoot(page, { width, height, html, out, transparent = false }) {
  await page.setViewportSize({ width, height });
  await page.setContent(`<!doctype html><style>${STAGE_CSS}</style>${html}`);
  await page.waitForLoadState("load");
  await page.screenshot({ path: out, omitBackground: transparent });
  console.log(`✓ ${path.relative(root, out)} (${width}×${height})`);
}

async function icons() {
  const browser = await chromium.launch({ channel: "chromium" });
  const page = await browser.newPage({ deviceScaleFactor: 1 });
  const dir = path.join(root, "public/icon");
  mkdirSync(dir, { recursive: true });
  for (const s of [16, 32, 48, 128]) {
    const html = `<img src="${svgUri}" width="${s}" height="${s}" style="display:block">`;
    await shoot(page, { width: s, height: s, html, out: path.join(dir, `${s}.png`), transparent: true });
  }
  await browser.close();
}

async function store() {
  const ext = path.join(root, ".output/chrome-mv3");
  const out = path.join(root, ".output/store");
  mkdirSync(out, { recursive: true });
  const context = await chromium.launchPersistentContext("", {
    channel: "chromium",
    args: [`--disable-extensions-except=${ext}`, `--load-extension=${ext}`],
  });
  const probe = await context.newPage();
  await probe.goto("chrome://extensions");
  const id = await probe.evaluate(
    () =>
      document
        .querySelector("extensions-manager")
        ?.shadowRoot?.querySelector("extensions-item-list")
        ?.shadowRoot?.querySelector("extensions-item")?.id ?? "",
  );
  if (!id) throw new Error("extension did not load");

  // Store icon: 128×128 with 96×96 artwork and 16 px transparent padding.
  const stage = await context.newPage();
  await shoot(stage, {
    width: 128,
    height: 128,
    transparent: true,
    html: `<img src="${svgUri}" width="96" height="96" style="display:block;margin:16px">`,
    out: path.join(out, "icon-128.png"),
  });

  // Promo tile 440×280 (mandatory small tile).
  await shoot(stage, {
    width: 440,
    height: 280,
    out: path.join(out, "promo-440x280.png"),
    html: `<div style="width:440px;height:280px;display:flex;align-items:center;gap:20px;padding:0 32px;box-sizing:border-box;background:linear-gradient(135deg,#f0f9ff,#e0f2fe)">
      <img src="${svgUri}" width="96" height="96"><div><div style="font-size:26px;font-weight:700;line-height:1.15">${esc(cfg.name)}</div>
      <div style="margin-top:8px;font-size:14px;color:#475569">${esc(cfg.tagline)}</div></div></div>`,
  });

  // Screenshots 1280×800: the extension's real UI page, framed with a caption.
  const ui = await context.newPage();
  for (const [i, shot] of cfg.screenshots.entries()) {
    await ui.setViewportSize({ width: cfg.uiWidth, height: 720 });
    await ui.goto(`chrome-extension://${id}/${shot.page}`);
    await ui.waitForLoadState("load");
    const height = Math.min(640, await ui.evaluate(() => document.body.scrollHeight));
    const png = await ui.screenshot({ clip: { x: 0, y: 0, width: cfg.uiWidth, height } });
    const uiUri = `data:image/png;base64,${png.toString("base64")}`;
    await shoot(stage, {
      width: 1280,
      height: 800,
      out: path.join(out, `screenshot-${i + 1}.png`),
      html: `<div style="width:1280px;height:800px;display:grid;grid-template-columns:1fr auto;align-items:center;gap:56px;padding:0 96px;box-sizing:border-box;background:linear-gradient(135deg,#f8fafc,#e0f2fe)">
        <div><div style="font-size:44px;font-weight:700;line-height:1.1">${esc(shot.caption)}</div>
        <div style="margin-top:20px;font-size:20px;color:#475569">${esc(cfg.name)}</div></div>
        <img src="${uiUri}" style="border-radius:12px;box-shadow:0 24px 60px -20px rgba(15,23,42,.35);border:1px solid #e2e8f0;background:#fff"></div>`,
    });
  }
  await context.close();
  writeFileSync(
    path.join(out, "README.txt"),
    "Generated by `tabmill assets` — upload these in the Developer Dashboard.\n",
  );
}

if (mode === "icons") await icons();
else if (mode === "store") await store();
else {
  console.error("usage: node scripts/assets.mjs icons|store");
  process.exit(2);
}
